style.css:
/* Roblox Christmas 3D Wonderland */

:root {
  /* Personalize as cores aqui */
  --my-green: #145638;
  --my-dark: #071f17;
  --my-red: #c52236;
  --my-gold: #ffd76a;
  --my-snow: #fffaf0;
}

/* Fundo de floresta natalina */
body {
  background:
    radial-gradient(circle at 15% 10%, #246c45 0%, transparent 35%),
    radial-gradient(circle at 85% 80%, #7e1929 0%, transparent 35%),
    linear-gradient(145deg, #061b14, #123d29 55%, #09251b) !important;
  color: var(--my-snow) !important;
}

/* Navegação de Natal */
header, nav {
  background: linear-gradient(135deg, #09271b, #17613b, #861b2c) !important;
  border-bottom: 3px solid var(--my-gold) !important;
  box-shadow: 0 5px 18px #0008 !important;
}

/* Cartões com profundidade */
main [class*="card"],
main [class*="Card"] {
  border-radius: 16px !important;
  border: 1px solid #d8b75c66 !important;
  box-shadow: 0 8px 18px #0006 !important;
  transition: transform .25s ease, box-shadow .25s ease !important;
}

main [class*="card"]:hover,
main [class*="Card"]:hover {
  transform: translateY(-5px) !important;
  box-shadow: 0 12px 24px #0009 !important;
}

/* Botões de presente */
button {
  background: linear-gradient(145deg, #df3548, #941628) !important;
  color: white !important;
  border: 1px solid var(--my-gold) !important;
  border-radius: 12px !important;
  box-shadow: 0 4px 0 #65101e, 0 7px 12px #0005 !important;
  transition: .2s ease !important;
}

button:hover {
  filter: brightness(1.2) !important;
  transform: translateY(-2px) !important;
}

/* Links dourados */
a {
  color: var(--my-gold) !important;
}

a:hover {
  color: #fff4c4 !important;
}

/* Campos de pesquisa */
input {
  background: #103b29 !important;
  color: white !important;
  border: 1px solid #c7a64e !important;
  border-radius: 12px !important;
}

/* Cartões e painéis */
[role="dialog"],
[role="menu"] {
  border: 1px solid #d6b45a !important;
  border-radius: 14px !important;
  box-shadow: 0 10px 25px #0008 !important;
}

/* Imagens */
img {
  border-radius: 12px;
}
